const byKey = new Map(METADATA_KEYS.map((entry) => [entry.key, entry]));

/** Exact, case-sensitive lookup matching upstream metadata keys. */
export function metadataKeyDefinition(key: string): MetadataKeyDefinition | undefined {
  return byKey.get(key);
}

export function isKnownMetadataKey(key: string): boolean {
  return byKey.has(key);
}

export function metadataKeyNamespace(key: string): string {
  const colon = key.indexOf(":");
  return colon === -1 ? "" : key.slice(0, colon);
}

const openPrefixes = METADATA_NAMESPACES.map((entry) => entry.prefix);

/** Keys in open namespaces are valid even when not enumerated. */
export function isOpenMetadataNamespaceKey(key: string): boolean {
  return openPrefixes.some((prefix) => prefix.length > 0 && key.startsWith(prefix));
}

